import {useCallback, useMemo, useState} from 'react'
import {Button} from '@primer/react'
import type {BaseOrganization} from '@github-ui/org-selector'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import {OrgsPanel} from '../components/panels/OrgsPanel'
import {ModelsPanel} from '../components/panels/ModelsPanel'
import {ModelValue, Page, type AppPayload, type CopilotModelValue} from '../types'
import {usePartialRouter} from '../contexts/PartialRouteContext'
import {useOrganizations} from '../hooks/use-organizations'
import {useSettings} from '../hooks/use-settings'
import {useLoading} from '../contexts/LoadingContext'

export function Rule() {
  const {canWrite} = useAppPayload<AppPayload>()
  const {navigate, ruleId} = usePartialRouter()
  const {setting, updateSetting} = useSettings()
  const {isLoading} = useLoading()
  const {organizationMap} = useOrganizations()

  const existingRule = useMemo(() => {
    if (typeof ruleId !== 'undefined') {
      return setting?.rules.find(_rule => ruleId === _rule.id)
    }
  }, [ruleId, setting])

  const [conditionValue, setConditionValue] = useState<string>(existingRule?.conditionExpression.value ?? '')
  const [parameterValue, setParameterValue] = useState<CopilotModelValue>(existingRule?.parameters.values ?? {})

  const setSanitizedParameterValue = useCallback(
    (updatedValues: CopilotModelValue) => {
      const newParameterValue = {...parameterValue, ...updatedValues}
      for (const key in updatedValues) {
        const value = updatedValues[key]
        if (value === ModelValue.Disabled) {
          delete newParameterValue[key]
        }
      }
      setParameterValue(newParameterValue)
    },
    [parameterValue, setParameterValue],
  )

  const selectedOrgs = useMemo<BaseOrganization[]>(() => {
    const conditionOrgs = conditionValue
      .split(',')
      .map(org => org.trim())
      .filter(org => org.length > 0)
    return conditionOrgs.map(org => organizationMap.get(org) ?? {name: org})
  }, [conditionValue, organizationMap])

  const setSelectedOrgs = useCallback(
    (orgs: BaseOrganization[]) => setConditionValue(orgs.map(({name}) => name).join(',')),
    [setConditionValue],
  )

  const submitRule = useCallback(async () => {
    if (!existingRule) {
      await updateSetting({
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        ...setting!,
        rules: [
          ...(setting?.rules ?? []),
          {
            id: -1,
            ruleType: 'add',
            conditionExpression: {
              targetableAttribute: 'organization.name',
              operation: 'in',
              value: conditionValue,
            },
            parameters: {
              values: parameterValue,
            },
          },
        ],
      })
    } else {
      const rules = setting?.rules ?? []
      const ruleIndexToUpdate = rules.findIndex(rule => rule.id === existingRule.id)
      if (ruleIndexToUpdate === -1) {
        return
      }
      await updateSetting({
        // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
        ...setting!,
        rules: [
          ...rules.slice(0, ruleIndexToUpdate),
          {
            id: -1,
            ...rules[ruleIndexToUpdate],
            conditionExpression: {
              targetableAttribute: 'organization.name',
              operation: 'in',
              value: conditionValue,
            },
            parameters: {
              values: parameterValue,
            },
          } as typeof existingRule,
          ...rules.slice(ruleIndexToUpdate + 1),
        ],
      })
    }
    navigate(Page.Overview)
  }, [existingRule, navigate, updateSetting, setting, conditionValue, parameterValue])

  const saveText = existingRule ? 'Update rule' : 'Create rule'

  return (
    <>
      <OrgsPanel selectedOrgs={selectedOrgs} setSelectedOrgs={setSelectedOrgs} />
      <ModelsPanel title="Allowed models" selectedModels={parameterValue} setModels={setSanitizedParameterValue} />
      <div className="d-flex flex-row flex-justify-start">
        <div className="d-flex gap-2">
          <Button variant="primary" onClick={submitRule} loading={isLoading} disabled={!canWrite}>
            {saveText}
          </Button>
          {/* eslint-disable-next-line @github-ui/web-vitals/no-sync-navigation-in-input-handler -- uses useNavigate under the hood */}
          <Button onClick={() => navigate(Page.Overview)}>Cancel</Button>
        </div>
      </div>
    </>
  )
}
