import {Link} from '@primer/react'
import {Fragment} from 'react/jsx-runtime'

/**
 * Returns true only for safe http/https URLs without embedded credentials.
 * Used to guard markdown link rendering against unsafe schemes (e.g. javascript:).
 */
function isValidUrl(value: string): boolean {
  let url
  try {
    // this can be any arbitrary URL, we don't want to append window.location.origin like the eslint rule wants
    // eslint-disable-next-line no-restricted-syntax
    url = new URL(value)
  } catch {
    return false
  }
  if (!['http:', 'https:'].includes(url.protocol)) return false
  if (url.username || url.password) return false
  if (!url.host) return false
  return true
}

/**
 * Renders a string with markdown-style `[text](url)` links as inline <Link> elements.
 * Only handles simple links — does not support escaped brackets/parentheses in link
 * text or URLs
 */
export function renderMarkdownLinks(text: string): React.ReactNode {
  const parts = text.split(/(\[[^[\]]+]\([^()]+\))/)
  return parts.map((part, i) => {
    if (!part) return null
    const linkMatch = part.match(/^\[([^[\]]+)]\(([^()]+)\)$/)
    const label = linkMatch?.[1]
    const url = linkMatch?.[2]
    if (label && url && isValidUrl(url)) {
      return (
        <Link
          // eslint-disable-next-line @eslint-react/no-array-index-key
          key={`link-${i}`}
          inline
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="Link--inTextBlock"
        >
          {label}
        </Link>
      )
    }
    // eslint-disable-next-line @eslint-react/no-array-index-key
    return <Fragment key={`text-${i}`}>{part}</Fragment>
  })
}
