import {useMemo, useState} from 'react'
import {SelectPanel, Button} from '@primer/react'
import type {ActionListGroupedListProps} from '@primer/react/deprecated'
import {AiModelIcon, TriangleDownIcon} from '@primer/octicons-react'
import {Category, type AugmentedActionListItemInput, type CopilotModelValue, type ModelWithValue} from '../types'
import {modelToActionListItem} from '../utils/model-to-action-list-item'
import {compareSelectedModels, updateModelsFromComparison} from '../utils/model-selector-helpers'

const groupMetadata: ActionListGroupedListProps['groupMetadata'] = [
  {groupId: Category.Fast, header: {title: 'Fast and cost-efficient', variant: 'filled'}},
  {groupId: Category.Versatile, header: {title: 'Versatile and highly intelligent', variant: 'filled'}},
  {groupId: Category.Powerful, header: {title: 'Most powerful at complex tasks', variant: 'filled'}},
]

type ModelSelectorProps = {
  isSyncing: boolean
  models: ModelWithValue[]
  selectedModels: ModelWithValue[]
  setModels(updatedModels: CopilotModelValue): void
  disabled?: boolean
}

export const ModelSelector = ({isSyncing, models, selectedModels, setModels, disabled = false}: ModelSelectorProps) => {
  const [filter, setFilter] = useState('')
  // where the open-to-close state of the selector is one "session"
  const [sessionSelectedModels, setSessionSelectedModels] = useState<ModelWithValue[]>(selectedModels)

  const togglePolicy = (newSelectedModels?: AugmentedActionListItemInput[]) => {
    setSessionSelectedModels(current =>
      compareSelectedModels({
        models,
        currentSelectedModels: current,
        newSelectedModels,
      }),
    )
  }

  const onSubmit = () => {
    const newModelValue = updateModelsFromComparison({
      currentSelectedModels: selectedModels,
      newSelectedModels: sessionSelectedModels,
    })
    setModels(newModelValue)
  }

  const filteredItems = useMemo(
    () =>
      models
        .filter(
          item =>
            // design guidelines say to always show selected item in the list
            sessionSelectedModels.some(selectedItem => selectedItem.name === item.name) ||
            // then filter the rest
            item.displayName.toLowerCase().includes(filter.toLowerCase()),
        )
        .map(item => modelToActionListItem(item)),
    [filter, models, sessionSelectedModels],
  )
  const itemInputModels = useMemo(
    () => sessionSelectedModels.map(model => modelToActionListItem(model)),
    [sessionSelectedModels],
  )
  const showGroups = useMemo(() => models.every(model => !!model.category), [models])
  const [open, setOpen] = useState(false)

  return (
    <SelectPanel
      variant="modal"
      loading={isSyncing}
      groupMetadata={showGroups ? groupMetadata : undefined}
      renderAnchor={({children, ...anchorProps}) => (
        <Button
          {...anchorProps}
          trailingAction={TriangleDownIcon}
          aria-haspopup="dialog"
          leadingVisual={AiModelIcon}
          disabled={disabled}
        >
          Add models
        </Button>
      )}
      title="Select models"
      placeholderText="Filter models"
      open={open}
      onOpenChange={(newOpen, gesture) => {
        setOpen(newOpen)
        if (gesture === 'selection') {
          onSubmit()
        }
      }}
      items={filteredItems}
      selected={itemInputModels}
      onCancel={() => setSessionSelectedModels(selectedModels)}
      //@ts-expect-error TODO types not being inferred based on items/selected props
      onSelectedChange={togglePolicy}
      onFilterChange={setFilter}
      overlayProps={{
        width: 'medium',
        height: 'medium',
      }}
    />
  )
}
