import type {PropsWithChildren} from 'react'
import {PermissionsProvider} from '../contexts/PermissionsContext'
import {EnabledFeaturesProvider} from '../contexts/EnabledFeaturesContext'
import {PartialRouterProvider} from '../contexts/PartialRouteContext'
import {PathsProvider} from '../contexts/PathsContext'
import {BannerProvider} from '../contexts/BannerContext'
import {DirtyValueProvider} from '../contexts/DirtySettingContext'
import {SettingProvider} from '../contexts/SettingContext'
import {LoadingProvider} from '../contexts/LoadingContext'
import type {Paths, EnabledFeatures} from '../types'

type AppProviderProps = {
  paths: Paths
  enabledFeatures?: EnabledFeatures
  canWrite: boolean
}

export function AppProvider({children, canWrite, enabledFeatures, paths}: PropsWithChildren<AppProviderProps>) {
  return (
    <PermissionsProvider canWrite={canWrite}>
      <PathsProvider paths={paths}>
        <EnabledFeaturesProvider enabledFeatures={enabledFeatures}>
          <LoadingProvider>
            <BannerProvider>
              <PartialRouterProvider>
                <DirtyValueProvider>
                  <SettingProvider>{children}</SettingProvider>
                </DirtyValueProvider>
              </PartialRouterProvider>
            </BannerProvider>
          </LoadingProvider>
        </EnabledFeaturesProvider>
      </PathsProvider>
    </PermissionsProvider>
  )
}
