import type {AugmentedActionListItemInput, ModelWithValue} from '../types'
import {PublisherIcon} from '../components/PublisherIcon'

export function modelToActionListItem(model: ModelWithValue): AugmentedActionListItemInput {
  return {
    groupId: model.category,
    leadingVisual: () => PublisherIcon({publisher: model.publisher}),
    text: model.displayName,
    id: model.name,
    value: model.value,
    description: model.warning,
    descriptionVariant: 'block',
  }
}
