import {useCallback, useRef, useState} from 'react'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

type UsePolicyMutationOptions = {
  policyUpdatePath: string
  policy: string
  initialValue?: string
  errorMessage?: string
}

export function usePolicyMutation({
  policyUpdatePath,
  policy,
  initialValue = 'disabled',
  errorMessage = 'There was a problem updating the policy.',
}: UsePolicyMutationOptions) {
  const [value, setValue] = useState(initialValue)
  const [error, setError] = useState<string | undefined>(undefined)
  const [isUpdating, setIsUpdating] = useState(false)
  // Guard against overlapping requests so only one update is ever in flight, which avoids any out-of-order response races.
  const isUpdatingRef = useRef(false)

  const clearError = useCallback(() => setError(undefined), [])

  const updateValue = useCallback(
    async (nextValue: string) => {
      // Ignore new selections while a request is in flight; the caller disables the control, but guard here too.
      if (isUpdatingRef.current) {
        return
      }
      isUpdatingRef.current = true
      setIsUpdating(true)
      setError(undefined)
      try {
        const response = await verifiedFetchJSON(`${policyUpdatePath}/${policy}`, {
          method: 'PATCH',
          body: {value: nextValue},
        })
        if (!response.ok) {
          throw new Error(`Failed to update ${policy} policy (${response.status})`)
        }
        // Commit the value only after the server confirms it, so the UI never shows an unsaved state.
        setValue(nextValue)
      } catch {
        setError(errorMessage)
      } finally {
        isUpdatingRef.current = false
        setIsUpdating(false)
      }
    },
    [policyUpdatePath, policy, errorMessage],
  )

  return {value, updateValue, error, clearError, isUpdating}
}
