import {ModelValue, type AugmentedActionListItemInput, type CopilotModelValue, type ModelWithValue} from '../types'

export type ModelSelectorHelperProps = {
  models?: ModelWithValue[]
  currentSelectedModels: ModelWithValue[]
  newSelectedModels?: AugmentedActionListItemInput[] | ModelWithValue[]
}

type CompareSelectedModelsProps = ModelSelectorHelperProps & {
  models: ModelWithValue[]
  newSelectedModels?: AugmentedActionListItemInput[]
}
export const compareSelectedModels = ({
  models,
  currentSelectedModels,
  newSelectedModels,
}: CompareSelectedModelsProps): ModelWithValue[] => {
  if (!newSelectedModels) {
    // If new selections is undefined or empty, return an empty array
    return []
  } else if (newSelectedModels.length > currentSelectedModels.length) {
    // If the new models is longer, a model has been added
    const currentModelNames = new Set(currentSelectedModels.map(m => m.name))
    // if a model is in the new list but not the current, it is the one being added
    const newModelId = newSelectedModels.find(({id}) => !currentModelNames.has(String(id)))?.id
    if (!newModelId) return currentSelectedModels

    // get the actual model after confirming it's the right one
    const newModel = models.find(model => model.name === String(newModelId))
    if (!newModel) return currentSelectedModels

    // append the model to the returned list and mark it as enabled
    return [
      ...currentSelectedModels,
      {
        ...newModel,
        value: ModelValue.Enabled,
      },
    ]
  } else {
    // From SelectPanel, you'll always either add or remove a model, so this must be removing 1
    const newModelIds = new Set(newSelectedModels.map(m => String(m.id)))
    // if a model is in the current list but not the new one, it's being removed
    const modelToRemoveIndex = currentSelectedModels.findIndex(({name}) => !newModelIds.has(name))
    // if found, just remove the model from the list, since the select panel only enables/disabled
    // the update will handle reverting values to the current if something was checked/unchecked in the same session
    if (modelToRemoveIndex !== -1) {
      return [
        ...currentSelectedModels.slice(0, modelToRemoveIndex),
        ...currentSelectedModels.slice(modelToRemoveIndex + 1),
      ]
    }
  }
  return currentSelectedModels
}

type UpdateModelsFromComparisonProps = ModelSelectorHelperProps & {newSelectedModels: ModelWithValue[]}
export const updateModelsFromComparison = ({
  currentSelectedModels,
  newSelectedModels,
}: UpdateModelsFromComparisonProps): CopilotModelValue => {
  const currentModelsByName = new Map(currentSelectedModels.map(model => [model.name, model.value]))
  const sessionModelNames = new Set(newSelectedModels.map(model => model.name))
  const updatedModels: CopilotModelValue = {}

  for (const sessionModel of newSelectedModels) {
    const persistedValue = currentModelsByName.get(sessionModel.name)
    if (!persistedValue) {
      updatedModels[sessionModel.name] = sessionModel.value
      continue
    }

    // if the value hasn't changed because of 0 or an even number of toggles, it can be skipped
    const isNoopUpdate =
      sessionModel.value === persistedValue ||
      (sessionModel.value === ModelValue.Enabled &&
        (persistedValue === ModelValue.Enabled || persistedValue === ModelValue.NoPolicy)) ||
      (sessionModel.value === ModelValue.Disabled &&
        (persistedValue === ModelValue.Disabled || persistedValue === ModelValue.Unconfigured))

    // only includes models with value changes, the update will merge the current state underneath
    if (!isNoopUpdate) {
      updatedModels[sessionModel.name] = sessionModel.value
    }
  }

  for (const persistedModel of currentSelectedModels) {
    if (!sessionModelNames.has(persistedModel.name)) {
      updatedModels[persistedModel.name] = ModelValue.Disabled
    }
  }

  return updatedModels
}
