import {type PropsWithChildren, createContext, use, useMemo, useState} from 'react'
import {announce} from '@github-ui/aria-live'
import type {Banner} from '../types'

export type BannerContext = {
  banner?: Banner
  clearBanner(): void
  setBanner(banner: Banner): void
}
export const BannerContext = createContext<BannerContext | undefined>(undefined)

export function BannerProvider({children}: PropsWithChildren) {
  const [currentBanner, setCurrentBanner] = useState<Banner | undefined>(undefined)
  const value = useMemo<BannerContext>(
    () => ({
      banner: currentBanner,
      clearBanner: () => setCurrentBanner(undefined),
      setBanner: (banner: Banner) => {
        announce(banner.message, {assertive: true})
        setCurrentBanner(banner)
      },
    }),
    [currentBanner, setCurrentBanner],
  )
  return <BannerContext value={value}>{children}</BannerContext>
}

export function useBannerContext(): BannerContext {
  const context = use(BannerContext)
  if (!context) {
    throw new Error('useBannerContext must be used within a BannerProvider')
  }
  return context
}
