import {Breadcrumbs, PageHeader} from '@primer/react'
import {Outlet} from '@github-ui/react-router'
import {AppProvider} from '../components/AppProvider'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {NavTabs} from '../components/NavTabs'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {useAppPayload} from '@github-ui/react-core/use-app-payload'
import type {AppPayload} from '../types'
import {ReadOnlyBanner} from '../components/ReadOnlyBanner'
import {PartialRouterProvider, usePartialRouter} from '../contexts/PartialRouteContext'

function LayoutBreadcrumbs() {
  const {page} = usePartialRouter()
  if (page === 'overview') {
    return (
      <Breadcrumbs>
        <Breadcrumbs.Item href={'.'}>Copilot</Breadcrumbs.Item>
        <Breadcrumbs.Item aria-current={'page'}>Models</Breadcrumbs.Item>
      </Breadcrumbs>
    )
  }
  return (
    <Breadcrumbs>
      {/* eslint-disable-next-line @github-ui/github-monorepo/no-relative-references-outside-package */}
      <Breadcrumbs.Item href={'../..'}>Copilot</Breadcrumbs.Item>
      <Breadcrumbs.Item href={'..'}>Models</Breadcrumbs.Item>
      <Breadcrumbs.Item aria-current={'page'}>Targeted model rule</Breadcrumbs.Item>
    </Breadcrumbs>
  )
}

function InnerLayout() {
  const {page, ruleId} = usePartialRouter()
  const {isAdmin, isStafftools} = useAppPayload<AppPayload>()
  const title = page === 'overview' ? 'Models' : ruleId ? `Edit targeted model rule` : 'Create targeted model rule'
  return (
    <div>
      {!isStafftools && !isAdmin && <ReadOnlyBanner />}
      {!isStafftools && <LayoutBreadcrumbs />}
      <PageHeader hasBorder={page === 'overview'} className="my-2">
        <PageHeader.Title as="h1">{title}</PageHeader.Title>
      </PageHeader>
      {!isStafftools && page === 'overview' && <NavTabs />}
      <div className="d-flex flex-column gap-3">
        <Outlet />
      </div>
    </div>
  )
}

export function Layout() {
  const {canWrite, isStafftools, paths} = useAppPayload<AppPayload>()
  const isUnconfiguredSeparate = !isFeatureEnabled('copilot_unconfigured_is_inherited')
  return (
    <AppProvider canWrite={!isStafftools && canWrite} enabledFeatures={{isUnconfiguredSeparate}} paths={paths}>
      <PartialRouterProvider>
        <InnerLayout />
      </PartialRouterProvider>
    </AppProvider>
  )
}
