import {type PropsWithChildren, createContext, use, useMemo} from 'react'
import type {EnabledFeatures} from '../types'

export const EnabledFeaturesContext = createContext<EnabledFeatures | undefined>(undefined)

export function EnabledFeaturesProvider({
  children,
  enabledFeatures,
}: PropsWithChildren<{enabledFeatures?: EnabledFeatures}>) {
  const value = useMemo(() => enabledFeatures ?? {}, [enabledFeatures])
  return <EnabledFeaturesContext value={value}>{children}</EnabledFeaturesContext>
}

export function useEnabledFeatures(): EnabledFeatures {
  const context = use(EnabledFeaturesContext)
  if (!context) {
    throw new Error('useEnabledFeatures must be used within a EnabledFeaturesProvider')
  }
  return context
}
